        for dish in self.selected_dishes:
            total += dish['price'] * dish['count'] * (1 - self.sales.get(dish['dish'], 0))
        return total

    def checkout(self):
        if self.selected_dishes:
            total = self.calculate_total()
            self.selected_dishes = []
            return total
