    def __init__(self, SCREEN_WIDTH, SCREEN_HEIGHT, BLOCK_SIZE, food_position):
        self.length = 1
        self.SCREEN_WIDTH = SCREEN_WIDTH
        self.SCREEN_HEIGHT = SCREEN_HEIGHT
        self.BLOCK_SIZE = BLOCK_SIZE
        self.positions = [((SCREEN_WIDTH / 2), (SCREEN_HEIGHT / 2))]
        self.score = 0
        self.food_position = food_position

    def move(self, direction):
        head_x, head_y = self.positions[0]
        new_head_x = (head_x + direction[0]) % self.SCREEN_WIDTH
        new_head_y = (head_y + direction[1]) % self.SCREEN_HEIGHT

        if (new_head_x, new_head_y) == self.food_position:
            self.eat_food()
        elif (new_head_x, new_head_y) in self.positions:
            self.reset()
        else:
            self.positions.insert(0, (new_head_x, new_head_y))
            if len(self.positions) > self.length:
                self.positions.pop()

    def random_food_position(self):
        while True:
            new_food_x = random.randrange(0, self.SCREEN_WIDTH, self.BLOCK_SIZE)
            new_food_y = random.randrange(0, self.SCREEN_HEIGHT, self.BLOCK_SIZE)
            if (new_food_x, new_food_y) not in self.positions:
                self.food_position = (new_food_x, new_food_y)
                break

    def reset(self):
        self.length = 1
        self.positions = [((self.SCREEN_WIDTH / 2), (self.SCREEN_HEIGHT / 2))]
        self.score = 0
        self.random_food_position()

    def eat_food(self):
        self.length += 1
        self.score += 100
        self.random_food_position()
